import{_ as t,o as i,c as s,a4 as o}from"./chunks/framework.BE47AOxC.js";const b=JSON.parse(`{"title":"ADR-0063 — Dépôt public de distribution de l'installateur","description":"Extrait de docs/adr/0063-depot-public-de-distribution.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0063 — Dépôt public de distribution de l'installateur","description":"Extrait de docs/adr/0063-depot-public-de-distribution.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0063-depot-public-de-distribution.md","filePath":"developpeurs/adr/0063-depot-public-de-distribution.md"}`),r={name:"developpeurs/adr/0063-depot-public-de-distribution.md"};function a(l,e,n,d,c,u){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0063--dépôt-public-de-distribution-de-linstallateur" tabindex="-1">ADR-0063 — Dépôt public de distribution de l&#39;installateur <a class="header-anchor" href="#adr-0063--dépôt-public-de-distribution-de-linstallateur" aria-label="Permalink to &quot;ADR-0063 — Dépôt public de distribution de l&#39;installateur {#adr-0063--dépôt-public-de-distribution-de-linstallateur}&quot;">​</a></h1><p><strong>Date :</strong> 30 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> recette réelle de la v0.2.0 : <code>installer.sh</code> et l&#39;archive de la pile répondaient 404 à un exploitant sans compte GitHub <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0045-deploiement-par-un-exploitant-non-developpeur">ADR-0045</a>, décision n°3 (installateur téléchargé depuis la release) ; complète l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0057-authenticite-des-images-a-l-installation">ADR-0057</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0045 fait joindre à chaque release GitHub l&#39;installateur (<code>installer.sh</code>) et l&#39;archive de la pile (<code>teuthis-deploy-X.Y.Z.tar.gz</code>), avec leurs sommes. L&#39;exploitant télécharge l&#39;installateur par <code>curl</code>, et l&#39;installateur télécharge l&#39;archive au même endroit.</p><p>Le dépôt du code, <code>Bastien-OC20/calamars</code>, est <strong>privé</strong>. Or les fichiers joints à une release d&#39;un dépôt privé ne se téléchargent pas sans compte : la recette de la v0.2.0 l&#39;a constaté (404 sur <code>installer.sh</code>). Les images GHCR, elles, sont publiques et leur signature cosign se vérifie, mais un exploitant ne peut pas installer.</p><p>Le Product Owner garde le dépôt du code privé.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Un dépôt public de distribution</strong>, <a href="https://github.com/Bastien-OC20/teuthis-cms-distribution" target="_blank" rel="noreferrer"><code>Bastien-OC20/teuthis-cms-distribution</code></a>, sous licence Apache-2.0, <strong>sans code source</strong> : un README et des releases. Chaque release <code>vX.Y.Z</code> y porte, octet pour octet, les quatre fichiers de la release du dépôt du code : <code>installer.sh</code>, <code>teuthis-deploy-X.Y.Z.tar.gz</code> et leurs sommes.</li><li><strong>Le workflow de publication les y dépose</strong> (<code>publication-images.yml</code>, job « Complète les notes de la release »), après la publication et la signature des images. Il crée la release si elle n&#39;existe pas, remplace les fichiers s&#39;il est relancé, puis <strong>relit <code>installer.sh</code> sans jeton</strong> et vérifie sa somme, comme un exploitant le fera. Un secret manquant arrête le job avec un message clair.</li><li><strong>Le jeton</strong> (<code>JETON_DISTRIBUTION</code>) est un jeton à droits fins créé par le Product Owner : <code>Contents: Read and write</code> sur ce seul dépôt, rien d&#39;autre, avec une expiration. Il ne donne aucun droit sur le dépôt du code.</li><li><strong>L&#39;installateur distingue deux dépôts</strong> (<code>deploy/installer.sh</code>) : <ul><li><code>DEPOT_DISTRIBUTION</code>, d&#39;où il télécharge l&#39;archive de la pile ;</li><li><code>DEPOT_GITHUB</code>, le dépôt du code, dont le workflow signe les images. C&#39;est l&#39;identité que cosign vérifie (ADR-0057), et elle ne change pas : une image doit venir du workflow du dépôt du code, pas d&#39;un dépôt où n&#39;importe quel détenteur du jeton peut déposer.</li></ul></li><li>Les commandes de la notice (<code>deploy/LISEZMOI.md</code>), de l&#39;en-tête de l&#39;installateur et de la section « Installer cette version » des notes pointent vers le dépôt de distribution.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Rendre le dépôt du code public</strong></td><td>Écartée par le Product Owner.</td></tr><tr><td><strong>Paquet GHCR <code>teuthis-deploy</code></strong> (artefact OCI)</td><td>Aucun secret à gérer, mais l&#39;exploitant devrait obtenir un jeton anonyme du registre puis télécharger un blob : une commande trop longue pour un exploitant non développeur (ADR-0045).</td></tr><tr><td><strong>Signer depuis le dépôt de distribution</strong></td><td>Le jeton de dépôt suffirait alors à publier une image « authentique » : l&#39;identité de signature doit rester le workflow du dépôt du code.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>L&#39;exploitant garde la même commande <code>curl</code>, sans compte GitHub.</li><li>La somme de l&#39;archive reste vérifiée par l&#39;installateur, et la signature des images reste liée au dépôt du code.</li></ul><p><strong>Négatives</strong></p><ul><li>Un secret de plus, qui <strong>expire</strong> : sans renouvellement, la publication s&#39;arrête à l&#39;étape de distribution (les images seront déjà poussées et signées ; relancer le job suffit une fois le jeton renouvelé).</li><li>Deux releases par version, à garder cohérentes : c&#39;est le workflow qui les écrit toutes deux, jamais une main.</li><li><strong>La v0.2.0 n&#39;est pas installable</strong> : son installateur, publié avant cette ADR, télécharge l&#39;archive depuis le dépôt du code. La v0.2.1 est la première version installable par un exploitant.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Dépôt de distribution créé, public, Apache-2.0, avec un README d&#39;installation ; secret <code>JETON_DISTRIBUTION</code> posé par le Product Owner (30/09/2026).</li><li>[x] Installateur à deux dépôts et test bats (« pile téléchargée depuis le dépôt de distribution, jamais depuis le dépôt du code ») ; workflow qui publie et relit sans jeton ; notice et procédure de publication à jour (<code>docs/publier-une-version.md</code>).</li><li>[x] Première release publiée dans le dépôt de distribution (v0.2.1), puis installation réelle depuis ce dépôt, sans compte GitHub, avec cosign v3 présent. <strong>Fait le 30/09/2026</strong> — release v0.2.1 (<code>calamars</code> et <code>teuthis-cms-distribution</code>), images <code>teuthis-api@sha256:78ce6fcb…</code> et <code>teuthis-admin@sha256:fdbccfe2…</code> publiques ; installation réelle sur un Ubuntu 24.04 jetable, sans compte GitHub, avec cosign v3.1.3 : installateur et archive vérifiés par leur somme, « Signature vérifiée » et « Empreinte conforme » pour les deux images, six services sains, <code>/api/sante</code> en HTTPS (200). <code>cosign verify</code> refuse la même image contre l&#39;étiquette <code>v9.9.9</code> (contre-épreuve).</li><li>[ ] Renouveler <code>JETON_DISTRIBUTION</code> avant son échéance.</li></ul>',17)])])}const h=t(r,[["render",a]]);export{b as __pageData,h as default};
